// Race baselines: the "vs the Orcs you've played" column.
//
// Two sources, one call. `resolve()` prefers the local one and says which it
// used, so nothing downstream has to know there are two and no screen can
// present a shipped number as if it came from the user's own games.
//
//   local  ProfileAggregate.raceBaseline over every OTHER seat of that race in
//          your corpus. The people you actually played, which matchmaking has
//          already put near your own level.
//   baked  js/race-baseline-data.js, generated by tools/build-race-baselines.js
//          from the repo's replay corpus. A cold start has no local history and
//          an empty column is a column doing nothing.
//
// The baked sample is professional games: effective APM medians run 395 to 565
// against a ladder player's 70 to 150. That is disclosed in the label rather
// than hidden, and the local source takes over at ProfileAggregate.MIN_RACE_N
// seats, which a normal history reaches inside a few dozen games.

(function () {
  'use strict';

  const RACE_NAME = { H: 'Human', O: 'Orc', E: 'Night Elf', U: 'Undead' };

  // The shipped table, in the shape ProfileAggregate.raceBaseline returns, so
  // the two are interchangeable at the call site.
  const fromBaked = (race) => {
    const baked = window.RaceBaselineData;
    const entry = baked && baked.races && baked.races[race];
    if (!entry) return null;
    const pick = (k) => ({
      median: entry[k] ? entry[k].median : null,
      n: entry[k] ? entry[k].n : 0
    });
    return {
      source: 'baked',
      race,
      seats: entry.seats || 0,
      dominanceAvg: pick('dominanceAvg'),
      apmEffective: pick('apmEffective'),
      heroKills: pick('heroKills')
    };
  };

  window.RaceBaselines = {
    /**
     * @param corpus every stored summary
     * @param race   'H' | 'O' | 'E' | 'U'
     * @param opts   { excludeName, excludeKey }: your name, and the game being
     *               looked at. Both are exclusions, because the benchmark must
     *               not contain the thing being benchmarked.
     */
    resolve (corpus, race, opts) {
      if (!race) return null;
      const PA = window.ProfileAggregate;
      const local = (PA && corpus) ? PA.raceBaseline(corpus, race, opts) : null;
      return local || fromBaked(race);
    },

    // What the column is called, which has to name the source. "vs Orc" over a
    // shipped professional median and "vs Orc" over eleven people you beat last
    // week are different claims and must not read the same.
    label (baseline) {
      if (!baseline) return null;
      const name = RACE_NAME[baseline.race] || baseline.race;
      return baseline.source === 'local'
        ? `vs ${name}, ${baseline.seats} you have played`
        : `vs ${name}, ladder sample`;
    },

    // The column head, which has to fit a narrow cell.
    head (baseline) {
      if (!baseline) return 'VS RACE';
      return `VS ${(RACE_NAME[baseline.race] || baseline.race).toUpperCase()}`;
    },

    RACE_NAME
  };
})();
